"""Generate crawlable visitor guides from the reviewed editorial data (no live claims)."""
import json, re, unicodedata, html
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT / 'scripts/guide-data.json').read_text())
DOMAIN = 'https://praiaideal.com'
SOURCE = 'https://www.centralbuzios.com/pt/praias/buzios'
OFFICIAL = 'https://www.turismo.rj.gov.br/cidades/armacao-dos-buzios/'
T = {
 'es': dict(home='Condiciones de hoy',beaches='Playas de Búzios',trails='Trilhas y paseos',guide='Planear tu día',partners='Paseos, autos y alianzas',map='Ver punto de referencia',profile='Geografía y viento',sand='Marea y arena disponible',access='Acceso y servicios',today='Ver esta playa hoy',source='Fuentes y revisión',review='Revisión editorial: 10/10/2026. No confirma acceso ni condiciones de hoy.',manual='Perfil geográfico manual local: las direcciones de viento entre {a}° y {b}° se consideran más resguardadas. No garantiza mar calmo, ausencia de olas ni baño seguro.',sandbody='La marea alta puede cubrir parte de la arena en cualquier playa. La pendiente, el oleaje y los cambios de arena modifican cuánto espacio queda. No tenemos umbrales de altura calibrados para esta playa ni medimos su ancho en vivo. Consultá la orientación actual antes de salir.',local='En Brava y Manguinhos, visitantes locales han reportado muy poca o ninguna franja de arena con el mar alto. Es una experiencia reportada, no una medición actual.',services='Confirmá el acceso final, estacionamiento, baños, sombra, precios y disponibilidad localmente. El mapa es un punto de referencia, no una ruta de senderismo.',kit='Llevá agua, calzado con agarre y protección solar. Descargá el recorrido, confirmá el acceso y organizá el regreso con luz. Evitá senderos con tormenta y rocas mojadas o alcanzadas por olas.',distance='Distancia y tiempo',unknown='Dependen del acceso y la variante; confirmar con guía local.',rain='Qué hacer si llueve o hay mucho viento',r1='Con lluvia, elegí un café o restaurante con espacio cubierto en el centro y confirmá horarios. No proponemos senderos ni recorridos por rocas mojadas.',r2='Rua das Pedras y Orla Bardot permiten un paseo por el centro cuando el tiempo acompaña: son lugares al aire libre, no alternativas cubiertas durante una tormenta.',r3='Manguinhos / Porto da Barra es una opción para el atardecer y gastronomía. Revisá el tiempo y no asumas que queda arena para sentarte.',p1='Todavía no hay ofertas comerciales activas ni descuentos exclusivos confirmados. No mostramos precios o promociones inventados.',p2='Cuando haya acuerdos, cada oferta identificará al proveedor, precio, qué incluye, vigencia y condiciones. El turista contratará, pagará y gestionará cambios o reclamos directamente con esa empresa.',p3='Si PraiaIdeal recibe una comisión, se informará junto al enlace. Los espacios patrocinados se identificarán como publicidad; pagar no cambiará el ranking de playas.',p4='Para operadores: proponé un beneficio real para visitantes, condiciones y enlace de reserva directo. La publicación está sujeta a revisión; no implica un acuerdo automático.',contact='Proponer una alianza',privacy='Privacidad',report='Proponer una corrección'),
 'pt': dict(home='Condições de hoje',beaches='Praias de Búzios',trails='Trilhas e passeios',guide='Planejar seu dia',partners='Passeios, carros e parcerias',map='Ver ponto de referência',profile='Geografia e vento',sand='Maré e faixa de areia',access='Acesso e serviços',today='Ver esta praia hoje',source='Fontes e revisão',review='Revisão editorial: 10/10/2026. Não confirma acesso ou condições de hoje.',manual='Perfil geográfico manual local: ventos entre {a}° e {b}° são considerados mais abrigados. Não garante mar calmo, ausência de ondas ou banho seguro.',sandbody='A maré alta pode cobrir parte da areia em qualquer praia. Inclinação, ondas e mudanças na areia alteram o espaço disponível. Não há alturas-limite calibradas para esta praia nem medição da largura ao vivo. Consulte a orientação atual antes de sair.',local='Na Brava e em Manguinhos, visitantes locais relataram pouca ou nenhuma faixa de areia com o mar alto. É uma experiência relatada, não medição atual.',services='Confirme acesso final, estacionamento, banheiros, sombra, preços e disponibilidade localmente. O mapa é uma referência, não uma rota de trilha.',kit='Leve água, calçado aderente e proteção solar. Baixe o percurso, confirme o acesso e organize a volta com luz. Evite trilhas com tempestades e rochas molhadas ou atingidas por ondas.',distance='Distância e tempo',unknown='Dependem do acesso e da variante; confirme com guia local.',rain='O que fazer com chuva ou vento forte',r1='Com chuva, escolha café ou restaurante com área coberta no centro e confirme horários. Não sugerimos trilhas ou rochas molhadas.',r2='Rua das Pedras e Orla Bardot oferecem um passeio pelo centro quando o tempo ajuda: são espaços ao ar livre, não alternativas cobertas numa tempestade.',r3='Manguinhos / Porto da Barra é uma opção para pôr do sol e gastronomia. Confira o tempo e não presuma areia disponível para sentar.',p1='Ainda não há ofertas comerciais ativas ou descontos exclusivos confirmados. Não exibimos preços ou promoções inventados.',p2='Cada futura oferta identificará fornecedor, preço, inclusões, validade e condições. O turista contratará, pagará e tratará alterações ou reclamações diretamente com a empresa.',p3='Se PraiaIdeal receber comissão, isso será informado junto ao link. Patrocínios serão identificados como publicidade; não alteram o ranking de praias.',p4='Operadores: proponham um benefício real, condições e link de reserva direto. A publicação depende de revisão; não representa acordo automático.',contact='Propor parceria',privacy='Privacidade',report='Propor correção'),
 'en': dict(home='Today’s conditions',beaches='Búzios beaches',trails='Trails and walks',guide='Plan your day',partners='Tours, cars and partnerships',map='View reference location',profile='Geography and wind',sand='Tide and exposed sand',access='Access and facilities',today='View this beach today',source='Sources and review',review='Editorial review: 10 Oct 2026. Does not confirm current access or conditions.',manual='Manual local geography profile: winds from {a}° to {b}° are considered more sheltered. This does not guarantee calm water, no waves or safe swimming.',sandbody='High tide can cover some sand at any beach. Slopes, waves and changes in sand affect the available space. No beach-specific tide-height thresholds are calibrated and beach width is not measured live. Check current guidance before leaving.',local='At Brava and Manguinhos, local visitors have reported little or no exposed sand at high water. This is a reported experience, not a current measurement.',services='Confirm final access, parking, toilets, shade, prices and availability locally. The map is a reference location, not a hiking route.',kit='Bring water, grippy footwear and sun protection. Download the route, confirm access and arrange a daylight return. Avoid trails during storms and wet rocks or rocks reached by waves.',distance='Distance and time',unknown='Depend on access and route variant; confirm with a local guide.',rain='What to do in rain or strong wind',r1='In rain, choose a café or restaurant with covered seating in the center and check opening times. Wet trails and rocky walks are not suggested.',r2='Rua das Pedras and Orla Bardot offer a central walk when weather allows: these are outdoor spaces, not covered alternatives during storms.',r3='Manguinhos / Porto da Barra is an option for sunset and dining. Check the forecast and do not assume sand is available for sitting.',p1='No active commercial offers or confirmed exclusive discounts yet. No invented prices or promotions are displayed.',p2='Future offers will identify the provider, price, inclusions, validity and conditions. Visitors will book, pay and handle changes or complaints directly with that company.',p3='Any commission paid to PraiaIdeal will be disclosed beside the link. Sponsored spaces will be labeled as advertising and will not change the beach ranking.',p4='Operators: propose a real visitor benefit, conditions and a direct booking link. Publication requires review and does not automatically establish an agreement.',contact='Propose a partnership',privacy='Privacy',report='Propose a correction')
}
CSS = '''*{box-sizing:border-box}body{margin:0;background:#f3f7f8;color:#203341;font:17px/1.65 system-ui,sans-serif}header,main,footer{max-width:960px;margin:auto;padding:24px}header{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px}a{color:#036b87;text-underline-offset:3px}nav{display:flex;flex-wrap:wrap;gap:16px}h1{font-size:clamp(2rem,5vw,3.4rem);line-height:1.15;letter-spacing:-.04em}h2{font-size:1.35rem}article,.card{background:white;border:1px solid #dbe6e9;border-radius:20px;padding:24px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.grid .card{margin:0}.button{display:inline-block;background:#086e88;color:white;padding:12px 18px;border-radius:12px;text-decoration:none;font-weight:700;margin:8px 8px 8px 0}.note{background:#fff1cb;border-left:4px solid #db9a1d;padding:16px;border-radius:12px}.muted{color:#526775;font-size:.9rem}img{width:100%;max-height:350px;object-fit:cover;border-radius:16px}footer{border-top:1px solid #dbe6e9;font-size:.9rem}a:focus-visible{outline:3px solid #d89713;outline-offset:4px}'''

def esc(x): return html.escape(str(x),quote=True)
def slug(x): return re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFD',x).encode('ascii','ignore').decode().lower()).strip('-')
def prefix(lang): return '/' if lang=='es' else '/'+lang+'/'
def link(label,url,button=False): return f'<a class="{"button" if button else ""}" href="{esc(url)}">{esc(label)}</a>'
def paragraph(text,cls=''): return f'<p class="{cls}">{esc(text)}</p>'
def section(title,body): return f'<article><h2>{esc(title)}</h2>{body}</article>'
urls=[]
def page(lang,path,title,desc,body):
 t=T[lang];url=DOMAIN+prefix(lang)+path
 alternates=''.join(f'<link rel="alternate" hreflang="{l}" href="{DOMAIN+prefix(l)+path}">' for l in T)
 nav=''.join(link(t[k],('/?lang='+lang) if k=='home' else prefix(lang)+p) for k,p in [('home',''),('beaches','playas/'),('trails','trilhas/'),('guide','guia/')])
 langs=' · '.join(link(l.upper(),prefix(l)+path) for l in T)
 data={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url,'inLanguage':lang}
 content=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | PraiaIdeal</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{url}">{alternates}<meta property="og:title" content="{esc(title)} | PraiaIdeal"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><link rel="icon" href="/icono.svg"><style>{CSS}</style><script type="application/ld+json">{json.dumps(data,ensure_ascii=False)}</script></head><body><header>{link('PraiaIdeal','/?lang='+lang)}<nav aria-label="Navigation">{nav}</nav><div>{langs}</div></header><main><h1>{esc(title)}</h1><p class="muted">{esc(desc)}</p>{body}</main><footer>{link(t['partners'],prefix(lang)+'alianzas/')} · {link(t['privacy'],'/privacidade.html')}<p>{esc(t['review'])}</p></footer></body></html>'''
 dest=ROOT/(prefix(lang).strip('/')+'/'+path).lstrip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content,encoding='utf-8');urls.append(url)

for lang,t in T.items():
 cards=[]
 for p in DATA['beaches']:
  path='playas/'+slug(p['nombre'])+'/'
  desc=p[lang];cards.append('<div class="card"><h2>'+link(p['nombre'],prefix(lang)+path)+'</h2>'+paragraph(desc)+'</div>')
  today=f'/?beach={p["id"]}&lang={lang}'
  body=link(t['today'],today,True)+link(t['map'],f'https://www.google.com/maps/search/?api=1&query={p["lat"]},{p["lon"]}',True)
  body+=section(t['profile'],paragraph(t['manual'].format(a=p['prot'][0],b=p['prot'][1])))
  body+=section(t['sand'],paragraph(t['sandbody'])+(paragraph(t['local'],'note') if p['id'] in [4,9] else ''))
  note=DATA['access'].get(str(p['id']));body+=section(t['access'],(paragraph(note[lang]) if note else '')+paragraph(t['services']))
  body+=section(t['source'],paragraph(t['review'])+link('CentralBúzios',SOURCE)+(link(t['access'],note['source']) if note else '')+paragraph('PraiaIdeal: '+t['profile'])+link(t['report'],'https://github.com/dgimenez6/praiaideal/issues/new'))
  page(lang,path,p['nombre']+' · Búzios',desc+' · '+t['profile']+', '+t['sand'].lower()+'.',body)
 page(lang,'playas/',t['beaches'],t['guide']+' · PraiaIdeal','<div class="grid">'+''.join(cards)+'</div>')
 cards=[]
 for i,(p,d) in enumerate(zip(DATA['trails'],DATA['details'])):
  path='trilhas/'+slug(p['nombre'])+'/';desc=d[lang];cards.append('<div class="card"><h2>'+link(p['nombre'],prefix(lang)+path)+'</h2>'+paragraph(desc)+'</div>')
  from urllib.parse import quote
  body=f'<img src="/trilha{i+1}.jpg" alt="{esc(p["nombre"])}">'+section(t['trails'],paragraph(desc))+section(t['distance'],paragraph(d.get('distance',{}).get(lang,t['unknown'])))+section(t['access'],paragraph(t['kit'])+paragraph(t['services'],'muted'))
  body+=link(t['map'],'https://www.google.com/maps/search/?api=1&query='+quote(d['start']),True)
  body+=section(t['source'],paragraph(t['review'])+link(t['source'],d['source'])+(link(' '+t['source'],d['extraSource']) if d.get('extraSource') else ''))
  page(lang,path,p['nombre']+' · Búzios',desc,body)
 page(lang,'trilhas/',t['trails'],t['guide']+' · PraiaIdeal','<div class="grid">'+''.join(cards)+'</div>')
 body=section(t['rain'],''.join(paragraph(t[k]) for k in ['r1','r2','r3']))+link(t['home'],'/?lang='+lang,True)+section(t['source'],link('SETUR RJ',OFFICIAL))
 page(lang,'guia/',t['guide'],t['rain'],body)
 body=''.join(section(t['partners'] if k=='p1' else t['source'] if k=='p4' else t['partners'],paragraph(t[k])) for k in ['p1','p2','p3','p4'])
 body+=link(t['contact'],'https://wa.me/5522997601592?text='+quote('Hola Damian, quiero proponer una alianza para PraiaIdeal. Empresa, servicio y beneficio: '),True)
 page(lang,'alianzas/',t['partners'],t['p1'],body)

urls.insert(0,DOMAIN+'/');urls.append(DOMAIN+'/privacidade.html')
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+esc(u)+'</loc></url>\n' for u in urls)+'</urlset>\n',encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://praiaideal.com/sitemap.xml\n',encoding='utf-8')
print(f'Generated {len(urls)-2} guide pages + sitemap and robots.txt')
